"""Tests for interval merging functionality."""

import pytest
from intervals import merge_intervals


class TestMergeIntervalsBasics:
    """Test basic functionality of merge_intervals."""

    def test_empty_list(self):
        """Empty list returns empty list."""
        assert merge_intervals([]) == []

    def test_single_interval(self):
        """Single interval is returned as-is."""
        assert merge_intervals([(1, 5)]) == [(1, 5)]

    def test_single_interval_zero_width(self):
        """Single point interval (start == end)."""
        assert merge_intervals([(3, 3)]) == [(3, 3)]


class TestMergeIntervalsOrdering:
    """Test that results are sorted by start regardless of input order."""

    def test_already_sorted(self):
        """Already sorted intervals."""
        assert merge_intervals([(1, 2), (3, 4), (5, 6)]) == [(1, 2), (3, 4), (5, 6)]

    def test_reverse_sorted(self):
        """Reverse sorted intervals become sorted."""
        assert merge_intervals([(5, 6), (3, 4), (1, 2)]) == [(1, 2), (3, 4), (5, 6)]

    def test_random_order(self):
        """Randomly ordered intervals are sorted in result."""
        assert merge_intervals([(3, 4), (1, 2), (5, 6)]) == [(1, 2), (3, 4), (5, 6)]


class TestMergeIntervalsOverlapping:
    """Test merging of overlapping intervals."""

    def test_two_overlapping_intervals(self):
        """Two overlapping intervals merge."""
        assert merge_intervals([(1, 3), (2, 5)]) == [(1, 5)]

    def test_multiple_overlapping_intervals(self):
        """Multiple overlapping intervals merge into one."""
        assert merge_intervals([(1, 3), (2, 5), (4, 7)]) == [(1, 7)]

    def test_overlapping_in_random_order(self):
        """Overlapping intervals merge regardless of input order."""
        assert merge_intervals([(4, 7), (1, 3), (2, 5)]) == [(1, 7)]

    def test_partial_overlap_at_start(self):
        """Intervals overlapping at the start of the second."""
        assert merge_intervals([(1, 4), (3, 6)]) == [(1, 6)]

    def test_partial_overlap_at_end(self):
        """Intervals overlapping at the end of the first."""
        assert merge_intervals([(3, 6), (1, 4)]) == [(1, 6)]


class TestMergeIntervalsTouching:
    """Test merging of touching (adjacent) intervals."""

    def test_touching_intervals_merge(self):
        """Touching closed intervals merge: (1, 3) and (3, 5) give (1, 5)."""
        assert merge_intervals([(1, 3), (3, 5)]) == [(1, 5)]

    def test_touching_in_reverse_order(self):
        """Touching intervals merge regardless of order."""
        assert merge_intervals([(3, 5), (1, 3)]) == [(1, 5)]

    def test_multiple_touching_intervals(self):
        """Multiple touching intervals all merge together."""
        assert merge_intervals([(1, 2), (2, 3), (3, 4)]) == [(1, 4)]

    def test_touching_with_overlap(self):
        """Mix of touching and overlapping intervals."""
        assert merge_intervals([(1, 3), (3, 5), (5, 7)]) == [(1, 7)]


class TestMergeIntervalsNested:
    """Test intervals that are fully inside other intervals."""

    def test_interval_inside_another(self):
        """Interval fully inside another does not shrink the outer one."""
        assert merge_intervals([(1, 5), (2, 3)]) == [(1, 5)]

    def test_interval_inside_in_reverse_order(self):
        """Nested interval in reverse order."""
        assert merge_intervals([(2, 3), (1, 5)]) == [(1, 5)]

    def test_multiple_intervals_inside_one(self):
        """Multiple intervals inside a larger one."""
        assert merge_intervals([(1, 10), (2, 3), (4, 5), (6, 7)]) == [(1, 10)]

    def test_nested_intervals_with_overlap(self):
        """Mix of nested and overlapping intervals."""
        assert merge_intervals([(1, 10), (2, 3), (8, 15)]) == [(1, 15)]

    def test_same_start_different_end(self):
        """Intervals with same start but different end."""
        assert merge_intervals([(1, 5), (1, 3)]) == [(1, 5)]

    def test_same_end_different_start(self):
        """Intervals with same end but different start."""
        assert merge_intervals([(1, 5), (3, 5)]) == [(1, 5)]

    def test_identical_intervals(self):
        """Identical intervals merge to one."""
        assert merge_intervals([(1, 5), (1, 5)]) == [(1, 5)]


class TestMergeIntervalsComplex:
    """Test complex scenarios with multiple interval types."""

    def test_multiple_separate_groups(self):
        """Multiple groups of intervals that merge separately."""
        assert merge_intervals([(1, 2), (3, 4), (5, 6)]) == [(1, 2), (3, 4), (5, 6)]

    def test_two_groups_with_touching_boundary(self):
        """Two groups with touching boundary merge into one."""
        assert merge_intervals([(1, 2), (2, 3), (5, 6)]) == [(1, 3), (5, 6)]

    def test_three_groups_merge(self):
        """Three groups eventually merge into one."""
        assert merge_intervals([(1, 2), (2, 3), (3, 4)]) == [(1, 4)]

    def test_complex_mix(self):
        """Complex mix of overlapping, touching, and nested intervals."""
        result = merge_intervals([(5, 8), (1, 3), (2, 6), (7, 10), (4, 5)])
        assert result == [(1, 10)]

    def test_many_intervals(self):
        """Many intervals with various relationships."""
        intervals = [(1, 2), (4, 5), (3, 6), (7, 8), (2, 3), (8, 9), (5, 7)]
        assert merge_intervals(intervals) == [(1, 9)]


class TestMergeIntervalsNegativeNumbers:
    """Test with negative numbers."""

    def test_negative_intervals(self):
        """Intervals with negative numbers."""
        assert merge_intervals([(-5, -1), (-3, 0)]) == [(-5, 0)]

    def test_negative_and_positive(self):
        """Mix of negative and positive intervals."""
        assert merge_intervals([(-5, -1), (0, 3), (-2, 1)]) == [(-5, 3)]

    def test_negative_single_interval(self):
        """Single negative interval."""
        assert merge_intervals([(-10, -5)]) == [(-10, -5)]


class TestMergeIntervalsZeroWidth:
    """Test with zero-width intervals (point intervals)."""

    def test_point_intervals(self):
        """Zero-width intervals (points)."""
        assert merge_intervals([(1, 1), (2, 2)]) == [(1, 1), (2, 2)]

    def test_point_touching_interval(self):
        """Point interval touching a regular interval."""
        assert merge_intervals([(1, 1), (1, 3)]) == [(1, 3)]

    def test_point_inside_interval(self):
        """Point interval inside a regular interval."""
        assert merge_intervals([(1, 3), (2, 2)]) == [(1, 3)]

    def test_consecutive_point_intervals(self):
        """Consecutive point intervals merge."""
        assert merge_intervals([(1, 1), (2, 2), (3, 3)]) == [(1, 3)]


class TestMergeIntervalsImmutability:
    """Test that the input list is not modified."""

    def test_input_not_modified(self):
        """Input list is not modified."""
        original = [(3, 5), (1, 2)]
        copy = original.copy()
        merge_intervals(original)
        assert original == copy

    def test_returns_new_list(self):
        """Result is a new list, not the input list."""
        input_list = [(1, 5)]
        result = merge_intervals(input_list)
        assert result is not input_list
        assert result == input_list

    def test_returns_new_tuples(self):
        """Result contains new tuples, not shared from input."""
        input_list = [(1, 5), (2, 3)]
        result = merge_intervals(input_list)
        # Verify it's a different list
        assert result is not input_list
        # Verify the merged intervals
        assert result == [(1, 5)]


class TestMergeIntervalsErrorHandling:
    """Test error handling."""

    def test_invalid_interval_start_greater_than_end(self):
        """Raises ValueError if start > end."""
        with pytest.raises(ValueError, match="invalid interval"):
            merge_intervals([(5, 1)])

    def test_invalid_interval_in_list(self):
        """Raises ValueError when any interval has start > end."""
        with pytest.raises(ValueError, match="invalid interval"):
            merge_intervals([(1, 2), (5, 3), (6, 8)])

    def test_error_message_contains_interval(self):
        """Error message contains the invalid interval."""
        with pytest.raises(ValueError, match=r"\(5, 1\)"):
            merge_intervals([(5, 1)])

    def test_error_with_negative_invalid_interval(self):
        """Error for invalid interval with negative numbers."""
        with pytest.raises(ValueError, match="invalid interval"):
            merge_intervals([(-1, -5)])

